import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/search', methods=['POST'])
def search():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Invalid input"}), 400

    search_content = data.get('search_content')
    search_filename = data.get('search_filename')
    search_dir = data.get('search_dir')

    if search_dir is not None and not isinstance(search_dir, str):
        return jsonify({"error": "Invalid input"}), 400

    base_dir = os.path.join('/data', search_dir) if search_dir else '/data'

    if not os.path.isdir(base_dir):
        return jsonify({"files": []}), 200

    matches = []

    for root, _, files in os.walk(base_dir):
        for name in files:
            # Check filename
            if search_filename and name.startswith(search_filename):
                matches.append(os.path.join(root, name))
                continue

            # Check content
            if search_content is not None:
                filepath = os.path.join(root, name)
                try:
                    with open(filepath, 'rb') as f:
                        content = f.read()
                    if isinstance(search_content, str):
                        if search_content.encode('utf-8') in content:
                            matches.append(filepath)
                    else:
                        # Handle non-string content (e.g. bytes, numbers)
                        if search_content in content:
                            matches.append(filepath)
                except (OSError, UnicodeDecodeError):
                    continue

    return jsonify({"files": matches}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
